/**
 * Unit tests for {@link Line#revert()}.
 */
public class Line_revert_TriageGen2Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testRevertWithStandardDirection() {
        // Setup: Line passing through (1, 1, 1) with direction (1, 0, 0)
        Vector3D origin = new Vector3D(1.0, 1.0, 1.0);
        Vector3D direction = new Vector3D(1.0, 0.0, 0.0);
        Line line = new Line(origin, origin.add(direction));

        // Execution
        Line reverted = line.revert();

        // Verification
        // The method defines: new Line(zero, zero.subtract(direction))
        // where zero is Vector3D.ZERO
        // Expected origin: (0, 0, 0)
        // Expected direction: (0, 0, 0) - (1, 0, 0) = (-1, 0, 0)

        assertNotNull("Reverted line should not be null", reverted);

        // Verify origin is (0,0,0)
        assertEquals("Reverted origin X should be 0", 0.0, reverted.getOrigin().getX(), EPSILON);
        assertEquals("Reverted origin Y should be 0", 0.0, reverted.getOrigin().getY(), EPSILON);
        assertEquals("Reverted origin Z should be 0", 0.0, reverted.getOrigin().getZ(), EPSILON);

        // Verify direction is -direction
        Vector3D expectedDirection = direction.negate();
        assertEquals("Reverted direction X should be -1", expectedDirection.getX(), reverted.getDirection().getX(), EPSILON);
        assertEquals("Reverted direction Y should be 0", expectedDirection.getY(), reverted.getDirection().getY(), EPSILON);
        assertEquals("Reverted direction Z should be 0", expectedDirection.getZ(), reverted.getDirection().getZ(), EPSILON);
    }

    @Test
    public void testRevertWithComplexDirection() {
        // Setup: Line with complex direction
        Vector3D origin = new Vector3D(5.0, -2.0, 3.0);
        Vector3D direction = new Vector3D(1.2, 3.4, -5.6);
        Line line = new Line(origin, origin.add(direction));

        // Execution
        Line reverted = line.revert();

        // Verification
        Vector3D expectedDirection = direction.negate();

        assertEquals("Reverted origin should be ZERO", Vector3D.ZERO, reverted.getOrigin());
        assertEquals("Reverted direction should be negated original direction", expectedDirection, reverted.getDirection());
    }

    @Test
    public void testRevertWithNegativeDirection() {
        // Setup: Line pointing in negative direction
        Vector3D origin = new Vector3D(0, 0, 0);
        Vector3D direction = new Vector3D(-1.0, -1.0, -1.0);
        Line line = new Line(origin, origin.add(direction));

        // Execution
        Line reverted = line.revert();

        // Verification
        // Expected direction: -(-1, -1, -1) = (1, 1, 1)
        Vector3D expectedDirection = new Vector3D(1.0, 1.0, 1.0);
        assertEquals("Reverted direction should be positive", expectedDirection, reverted.getDirection());
    }
}
